<?php
namespace App\Services;
use Illuminate\Support\Facades\DB;
class ScheduleReplacementApplier {
 public function apply(int $periodId): array {$applied=0;$skipped=0;foreach(DB::table('schedule_replacements')->where('academic_period_id',$periodId)->cursor() as $r){$p=json_decode($r->payload,true)?:[];$date=$r->replacement_date;if(!$date){$skipped++;continue;}$lessonNo=$this->int($p,['hour','lesson_number','lesson']);$mode=DB::table('academic_periods')->where('id',$periodId)->value('lesson_unit_mode') ?: 'lesson';if($mode==='pair'&&$lessonNo)$lessonNo=intdiv($lessonNo-1,2)+1;$groupSource=$this->int($p,['class_id','klass_id','group_id']);if(!$lessonNo||$groupSource===null){$skipped++;continue;}$groupId=DB::table('study_groups')->where('source_id',$groupSource)->value('id');$lesson=DB::table('lesson_occurrences')->where('academic_period_id',$periodId)->whereDate('lesson_date',$date)->where('lesson_number',$lessonNo)->where('study_group_id',$groupId)->first();if(!$lesson){$skipped++;continue;}if($this->bool($p,['cancelled','canceled','cancel'])){DB::table('lesson_occurrences')->where('id',$lesson->id)->update(['status'=>'cancelled','updated_at'=>now()]);$applied++;continue;}$u=['status'=>'replaced','updated_at'=>now()];foreach([['teacher_id','teachers',['teacher_id']],['subject_id','subjects',['subject_id']],['room_id','rooms',['room_id']]] as [$field,$table,$keys]){$src=$this->int($p,$keys);if($src!==null){$id=DB::table($table)->where('source_id',$src)->value('id');if($id)$u[$field]=$id;}}DB::table('lesson_occurrences')->where('id',$lesson->id)->update($u);$applied++;}return compact('applied','skipped');}
 private function int(array $a,array $keys): ?int {foreach($keys as $k)if(isset($a[$k])&&$a[$k]!=='')return (int)$a[$k];return null;}
 private function bool(array $a,array $keys): bool {foreach($keys as $k)if(isset($a[$k])&&in_array(strtolower((string)$a[$k]),['1','yes','true','да'],true))return true;return false;}
}
